// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address owner, address spender) public {
        vm.assume(caller != address(0xdead));
        vm.assume(owner != address(0));
        vm.assume(spender != address(0));

        // Record wards before
        uint256 wardsBefore = c.wards(caller);

        vm.prank(caller);
        c.allowance(owner, spender);

        uint256 wardsAfter = c.wards(caller);

        assertTrue(wardsBefore == wardsAfter, "wards should not change after allowance");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(0, bytes16(0), address(this), address(this), address(this)); 
    }

    function testFuzz_property(address sender, address tokenOwner, address spender) public {
        // Record wards values for some keys before the call
        // We'll check a few keys: tokenOwner, spender, sender, and address(0xdead)
        address[4] memory keys = [tokenOwner, spender, sender, address(0xdead)];
        uint256[4] memory before;
        for(uint256 i; i < 4; i++) {
            before[i] = c.wards(keys[i]);
        }

        // Make the allowance call
        vm.prank(sender);
        c.allowance(tokenOwner, spender);

        // Assert that wards didn't change for any of these keys
        for(uint256 i; i < 4; i++) {
            assertTrue(c.wards(keys[i]) == before[i]);
        }
    }
}

