pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address tokenOwner, address spender) public {
        vm.assume(caller != address(0));
        vm.assume(tokenOwner != address(0));
        vm.assume(spender != address(0));
        vm.prank(caller);
        c.allowance(tokenOwner, spender);
        // The contract constructor sets wards[msg.sender] = 1 (msg.sender = address(this) in setUp).
        // No function in the contract ever changes that value for this address.
        // So after any call, wards[address(this)] must still be 1.
        assertTrue(c.wards(address(this)) == 1, "wards[address(this)] should remain 1");
    }
}

