        // Also record wards[other] (should be 0)
        uint256 wardsOtherAfterRely = c.wards(other);
        // Call allowance
        c.allowance(address(0), address(0));
        // Check: wards[user] and wards[other] unchanged
        assertTrue(c.wards(user) == wardsUserAfterRely && c.wards(other) == wardsOtherAfterRely);
    }
}

