contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address sender, address user) public {
        vm.assume(sender != address(0) && user != address(0) && sender != user);
        // First ensure sender is authorized (rely on sender)
        vm.prank(address(this));
        c.rely(sender);
        // Now drive allowance from sender
        vm.prank(sender);
        c.allowance(user, user);
        // After allowance, check if sender still has authorization
        uint256 wardsSender = c.wards(sender);
        assertTrue(wardsSender == 1, "wards[sender] should be 1 after allowance");
    }
}

