pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(uint256 shares) public {
        // bound to avoid overflow or zero denominator issues in the reference
        vm.assume(shares <= type(uint256).max / 1e18);

        // Call the reference implementation via the contract's external interface
        (bool successP, bytes memory dataP) = address(c).call(
            abi.encodeWithSignature("convertToAssets(uint256)", shares)
        );
        require(successP, "Reference call reverted");
        uint256 assetsP = abi.decode(dataP, (uint256));

        // Since we cannot directly call the mutated version, we simulate the mutation logic here
        uint256 latestPrice = uint256(c.latestPrice());
        // If latestPrice is 0, the mutation would revert with division by zero, so skip
        vm.assume(latestPrice != 0);
        uint256 assetsM = shares * latestPrice / 1e18;

        // The general rule: For any valid shares, the reference output should not equal the mutation output
        // unless the mutation happens to produce the same result
        assertTrue(assetsP != assetsM || shares == 0 || latestPrice == 0, 
            "Mutant should produce different result from reference");
    }
}

